    /// The NeedsConfirmation refusals it can answer with (`WsError.needsConfirmation`) and the payload member
    /// a resend sets to accept each; `confirmation(_:)` looks one up by code.
    public var confirmations: [WsConfirmation] {
        switch self {
        case .authUserDelete:
            [
                WsConfirmation(
                    code: "user_delete", acceptField: "confirm",
                    summary:
                        """
                        The account (and the vaults it owns unless transfer_to is set) would be deleted: resend with\
                         confirm once the person agrees.
                        """
                ),
            ]
        case .recoveryPointDelete:
            [
                WsConfirmation(
                    code: "recovery_point_delete", acceptField: "confirm",
                    summary: "Deleting a snapshot or local version can't be undone: resend with confirm."
                ),
            ]
        case .recoveryRestore:
            [
                WsConfirmation(
                    code: "recovery_restore", acceptField: "token",
                    summary:
                        """
                        The plan's token is missing or wrong: resend with the token recovery.plan returned (shown with\
                         the plan's create / overwrite / remove counts).
                        """
                ),
                WsConfirmation(
                    code: "recovery_plan_expired", acceptField: nil,
                    summary: "The plan expired (30 minutes): plan again with recovery.plan and restore the new plan."
                ),
                WsConfirmation(
                    code: "recovery_unverified_version", acceptField: "accept_unverified",
                    summary:
                        """
                        Some versions were found in the bucket, not written by Vaulthalla: resend with\
                         accept_unverified only if the person trusts them.
                        """
                ),
            ]
        case .s3GatewayBucketsCreateRemoteCache:
            [
                WsConfirmation(
                    code: "encryption_waiver", acceptField: "accept_encryption_waiver",
                    summary:
                        """
                        The upstream bucket already holds data Vaulthalla did not write: resend with\
                         accept_encryption_waiver once the person accepts.
                        """
                ),
            ]
        case .storageVaultAdd:
            [
                WsConfirmation(
                    code: "encryption_waiver", acceptField: "accept_encryption_waiver",
                    summary:
                        """
                        The bucket already holds data Vaulthalla did not write (or encryption is being switched on\
                         over it): resend with accept_encryption_waiver once the person accepts.
                        """
                ),
                WsConfirmation(
                    code: "upstream_adoption", acceptField: "provision.accept_adoption",
                    summary:
                        """
                        provision mode adopt (or an existing unmanaged bucket) needs consent to adopt the bucket:\
                         resend with provision.accept_adoption.
                        """
                ),
            ]
        case .storageVaultRemove:
            [
                WsConfirmation(
                    code: "vault_upstream_key_loss", acceptField: "accept_key_loss",
                    summary:
                        """
                        The vault key was never exported and its S3 data would become unreadable: resend with\
                         accept_key_loss once the person accepts.
                        """
                ),
                WsConfirmation(
                    code: "vault_delete_now", acceptField: "confirm_now",
                    summary: "Deleting now skips the restore window: resend with confirm_now."
                ),
            ]
        case .storageVaultUpdate:
            [
                WsConfirmation(
                    code: "encryption_waiver", acceptField: "accept_encryption_waiver",
                    summary:
                        """
                        The bucket already holds data Vaulthalla did not write (or encryption is being switched on\
                         over it): resend with accept_encryption_waiver once the person accepts.
                        """
                ),
            ]
        case .upstreamBucketCleanup:
            [
                WsConfirmation(
                    code: "upstream_cleanup", acceptField: "confirm_token",
                    summary:
                        """
                        The confirm_token is missing, expired or no longer matches the bucket: run\
                         upstream.bucket.cleanup.preflight again and resend its confirm_token.
                        """
                ),
            ]
        case .upstreamBucketLifecycleSet:
            [
                WsConfirmation(
                    code: "upstream_destructive_lifecycle", acceptField: "accept_destructive",
                    summary: "Expiration deletes objects: resend with accept_destructive once the person accepts."
                ),
            ]
        case .upstreamBucketUnprotect:
            [
                WsConfirmation(
                    code: "upstream_unprotect", acceptField: "confirm",
                    summary: "Removing a bucket lock lets Vaulthalla act on the bucket again: resend with confirm."
                ),
            ]
        case .vaultKeysImport:
            [
                WsConfirmation(
                    code: "vault_key_import", acceptField: "confirm_name",
                    summary:
                        """
                        mode recover: the import would re-seal the listed key versions under this host's vault master\
                         (the error text says which): resend with confirm_name set to the vault's name (a string, not\
                         a flag) once the person typed it.
                        """
                ),
                WsConfirmation(
                    code: "vault_key_salvage", acceptField: "confirm_name",
                    summary:
                        """
                        Every mode salvage request that would write. It would create a fresh key version and\
                         re-encrypt every file the supplied key decrypts under it (the error text says which versions;\
                         files it can't decrypt are reported unrecoverable), and restore any attested versions as\
                         recover does; when no version needs salvage the text says so and only the restore happens.\
                         Resend with confirm_name set to the vault's name once the person typed it.
                        """
                ),
            ]
        case .vaultRecoverySuspend:
            [
                WsConfirmation(
                    code: "recovery_versioning_suspend", acceptField: "confirm",
                    summary: "Suspending versioning on the bucket: resend with confirm (existing versions are kept)."
                ),
            ]
        case .vaultRecoveryUpdate:
            [
                WsConfirmation(
                    code: "recovery_versioning_disclosure", acceptField: "disclosure_token",
                    summary:
                        """
                        Provider versioning needs the cost disclosure: show vault.recovery.disclosure and resend its\
                         disclosure_token (valid 10 minutes, and only while the figures are unchanged).
                        """
                ),
                WsConfirmation(
                    code: "recovery_versioning_unpriced", acceptField: "accept_unpriced",
                    summary:
                        "Some costs can't be priced: resend with accept_unpriced once the person accepts unknown costs."
                ),
                WsConfirmation(
                    code: "recovery_retention_shorten", acceptField: "accept_retention_shortening",
                    summary: "A shorter retention deletes history sooner: resend with accept_retention_shortening."
                ),
                WsConfirmation(
                    code: "upstream_adoption", acceptField: "accept_adoption",
                    summary:
                        "The vault's bucket is not managed by Vaulthalla yet: resend with accept_adoption to adopt it."
                ),
            ]
        default: []
        }
    }

    /// The command book's description.
    public var summary: String {
        switch self {
        case .authIsAuthenticated:
            "Whether the envelope token is a valid session for this socket."
        case .authLogin:
            """
            Sign in with a username and password. The access token comes back in the response envelope (`token`), the\
             refresh token as an HttpOnly cookie set at the handshake.
            """
        case .authLogout:
            "End the session (access and refresh tokens)."
        case .authRefresh:
            "Issue a new access token from the envelope token or the refresh cookie."
        case .authRegister:
            "Create a user. role is an admin role name or id; the password is required (only the CLI generates one)."
        case .authSecurityStatus:
            """
            Security posture warning for the signed-in account: the super admin's initial password file while the\
             generated password is still in use, else null.
            """
        case .authUserChangePassword:
            "Change (own, with old_password) or reset (another user's) a password."
        case .authUserDelete:
            """
            Delete a user. Without confirm the reply is a refusal with data.code 'user_delete' and the question to\
             ask. The user's vaults are destroyed unless transfer_to names who gets them.
            """
        case .authUserGet:
            "One user with its full roles and permissions."
        case .authUserGetByName:
            "One user by name."
        case .authUserUpdate:
            """
            Patch a user (the caller when id is absent). Role changes and deactivation end the account's sessions.\
             linux_uid, updated_by, protected, is_protected, system_only and password are refused.
            """
        case .authUsersList:
            "Users visible to the caller, slim projection (admin_role without permissions)."
        case .dashboardPreferencesGet:
            """
            The caller's saved dashboard layout for a key; exists is false (empty layout) when none is saved. A\
             non-object payload reads the default key.
            """
        case .dashboardPreferencesReset:
            """
            Delete the caller's saved layout for a key; deleted says whether one existed. A non-object payload resets\
             the default key.
            """
        case .dashboardPreferencesUpdate:
            """
            Save the caller's dashboard layout for a key (insert or replace). The layout is validated (at most 64 KiB\
             and 64 cards) and otherwise stored as sent.
            """
        case .deviceEndpoints:
            """
            Where this node's device listener can be reached (docs/reference/transfer-protocol.md §1.1): interface\
             addresses classified by range, <hostname>.local where an mDNS responder runs, and\
             device_server.advertise's configured names. Computed per call; never answered before a device is paired.
            """
        case .deviceIdentityRotate:
            """
            Replace this device's key: certificate is the new self-signed P-256 certificate (base64 DER), signature\
             the old key's ECDSA-P256-SHA256 (base64 DER) over "vh-device-rotate-v1" ‖ new_spki_sha256 ‖\
             server_spki_sha256 ‖ UInt64BE(timestamp). The old key keeps working until the first connection with the\
             new one. A retry from the old key naming the same new key succeeds again; another key is conflict.
            """
        case .deviceList:
            "The caller's devices, revoked ones included; with all, every user's (super admins only)."
        case .devicePairConfirm:
            """
            Reveal nonce_device. It must match the request's commitment (else the request is deleted: invalid); then\
             the request is shown to the window's owner with its code. The daemon never sends the code to the device.\
             Same key as the request only.
            """
        case .devicePairRequest:
            """
            Ask to pair this connection's key while a pairing window is open, committing to nonce_device\
             (SHA-256("vh-pair-commit-v1" ‖ device_spki_sha256 ‖ nonce_device)). Refused with no_pairing_window when\
             none is open, rate_limited past 10 per minute per address or 5 per window, conflict for a key this node\
             knows. One live request per key: a new one replaces it.
            """
        case .devicePairStatus:
            """
            How the request stands. Answered at once (no long poll): after pending, ask again in 2 s. Approved carries\
             the node's id and name and the device id; the device then pins the server key and reconnects, which makes\
             a Device session. Same key as the request only.
            """
        case .devicePairingApprove:
            """
            Approve a request with the code the device shows (number matching). Any other code denies the request\
             (invalid). Creates the device for the caller's account.
            """
        case .devicePairingClose:
            """
            Close the caller's own pairing window; its requests expire. any: whoever's window is open (super admins\
             only).
            """
        case .devicePairingDeny:
            "Deny a pending request; the device is told it was declined."
        case .devicePairingOpen:
            """
            Open a 10-minute pairing window owned by the caller (reopening extends it). One window per node: conflict\
             while another user's is open. Also says what to type into Desktop: the listener's port and whether\
             devices on other hosts can reach it (remote), and what the vaulthalla://pair link carries (node_id,\
             server_spki_sha256, endpoints; transfer-protocol.md §1.2).
            """
        case .devicePairingPending:
            """
            The caller's open window and its confirmed requests. Each offers three code_choices (random order): one is\
             the code the device shows, two are decoys fixed for the request. The real code is never returned on its\
             own.
            """
        case .deviceRemoteDisable:
            "Back to loopback only: the listener rebinds now and device sessions from other hosts close."
        case .deviceRemoteEnable:
            """
            Let devices on other hosts connect: the listener rebinds to every interface now, and stays that way across\
             restarts and upgrades (device_server.remote in config.yaml).
            """
        case .deviceRemoteStatus:
            """
            The device listener: loopback only or every interface, and whether it listens; diagnostics say where it is\
             bound, what devices are told, what the host firewall looks like (read-only, null when unknown) and when a\
             device last connected from a public address.
            """
        case .deviceRename:
            "Rename a device (its user, or a super admin)."
        case .deviceRevoke:
            """
            Unpair a device (its user, a super admin, or the device itself). Final: its live sessions close at once\
             and its key only ever gets pairing-only connections again.
            """
        case .deviceServerIdentity:
            "The server key's SPKI hash (the pin). A next key is never announced: a new server key means pairing again."
        case .emailConfigGet:
            "The email provider settings, the operator email policy and which provider secrets are stored."
        case .emailConfigUpdate:
            """
            Merge-patch the email and operator_emails settings sections (RFC 7386; other sections are ignored) and\
             save them through the same validation as settings.update.
            """
        case .emailHistory:
            "Operator email delivery history, newest first."
        case .emailProviderSecretSet:
            """
            Store provider credentials in the secrets manager: resend needs api_key; ses takes access_key_id and/or\
             secret_access_key (at least one). Values are write-only.
            """
        case .emailTestSend:
            """
            Send (or, with dry_run, only render and record) a test email. Without to, a dry run goes to the first\
             alerts recipient. status says which happened. Email disabled or provider none is a 'conflict'; a failing\
             provider answers without a code. Both are recorded in the history.
            """
        case .fsDirCreate:
            "Create a directory (Touch on the path)."
        case .fsDirList:
            """
            List a directory (List on the path). Children the caller cannot Lookup are left out, as in FUSE readdir,\
             and so is what they hold from child folders' size and counts and the folder's own size.
            """
        case .fsDownloadCancel:
            "Share sessions only: drop a transfer."
        case .fsDownloadChunk:
            "Share sessions only: read the next chunk (base64)."
        case .fsDownloadStart:
            "Share sessions only: start a chunked download of a file inside the share."
        case .fsEntryCopy:
            """
            Copy an entry or tree: Copy on every source, Read on source files, Write (files) or Touch (directories) at\
             each destination, all checked before anything is written.
            """
        case .fsEntryDelete:
            "Delete a file or directory tree (Delete on the path)."
        case .fsEntryMove:
            """
            Move an entry: Move on the source; into another folder also Write (files) or Touch (directories) at the\
             destination, for the entry and everything it carries.
            """
        case .fsEntryRename:
            """
            Rename an entry: Rename on the source; into another folder also Write (files) or Touch (directories) at\
             the destination, for the entry and everything it carries.
            """
        case .fsList:
            "fs.dir.list for console sessions; in a share session the share's view of the directory."
        case .fsMetadata:
            "One entry's metadata (Lookup on the path)."
        case .fsUploadCancel:
            "Abort the session's active ws upload."
        case .fsUploadFinish:
            "Finish the session's active ws upload."
        case .fsUploadStart:
            """
            Start a chunked ws upload (Write on the path). The console uploads over HTTP instead (POST\
             /upload/session); this is the native ws transfer.
            """
        case .groupAdd:
            "Create a group."
        case .groupGet:
            "One group by id."
        case .groupGetByName:
            "One group by name."
        case .groupMemberAdd:
            "Add a user to a group."
        case .groupMemberRemove:
            "Remove a user from a group."
        case .groupRemove:
            "Delete a group."
        case .groupUpdate:
            "Patch a group: name, description and linux_gid are each optional."
        case .groupsList:
            "Every group for group viewers; otherwise only the caller's own groups."
        case .groupsListByUser:
            "The groups a user belongs to."
        case .metaContractGet:
            """
            The contract this daemon was built from: contract_version, contract_hash (the whole document vh_usage\
             --json publishes), ws_hash (the ws command book, what the web console is generated from) and models_hash\
             (the model shapes the book refers to). Read-only, no secrets; needs a signed-in session (no build\
             fingerprinting before login).
            """
        case .metaHello:
            """
            The protocol handshake, first thing after connecting (after sign-in on the web socket; allowed where\
             meta.contract.get is: signed-in web, paired device and pairing-only sessions, never an unauthenticated or\
             share session). The client says what it is and the protocol range it speaks; the daemon answers its own\
             name and version, the protocol version this session now speaks (the newest both speak; kProtocolMin\
             without a range, as for a session that never says hello), its own range, its capabilities, every command\
             it registers and its contract identity. No overlap: ERROR protocol_unsupported with data {code,\
             server_min, server_max, server_version}. A paired device's client.version refreshes its app_version.
            """
        case .permissionGet:
            "One permission of the catalog by id."
        case .permissionGetByName:
            "One permission of the catalog by its qualified name."
        case .permissionsList:
            "The whole permission catalog."
        case .pricingBudgetLedgerList:
            """
            Reservation ledger rows, newest first. Non super admins must name a vault they can view or a gateway\
             credential they own.
            """
        case .pricingBudgetOverrideApprove:
            "Approve a pending override (super admins). A bare `id` is refused: send override_id."
        case .pricingBudgetOverrideDeny:
            "Deny a pending override (super admins). A bare `id` is refused: send override_id."
        case .pricingBudgetOverrideList:
            "Overrides, newest first. Super admins see all (or one vault's); others must name a vault they can view."
        case .pricingBudgetOverrideRequest:
            "Ask for a one-time override of exceeded enforce policies on a vault (vault sync Trigger permission)."
        case .pricingBudgetPolicyDisable:
            """
            Disable the policy of a scope (same authority as upsert). disabled is false when there was nothing to\
             disable.
            """
        case .pricingBudgetPolicyList:
            """
